// Writes corpus/extracted/index.js: one static import per extracted file, so both the Node run
// and the bundle for Hermes read the same extracted inputs.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), '../corpus/extracted')
const files = fs.readdirSync(DIR).filter(f => f.endsWith('.json')).sort()
const lines = [
    '// Generated by extract/write-index.mjs: the inputs the repository\'s own tests passed to the rules.',
    ...files.map((f, i) => `import f${i} from './${f}' with { type: 'json' }`),
    `export const extractedFiles = [${files.map((_, i) => `f${i}`).join(', ')}]`,
    ''
]
fs.writeFileSync(path.join(DIR, 'index.js'), lines.join('\n'))
console.log(`indexed ${files.length} extracted files`)
